"""Pydantic schemas for the local text-to-speech API."""

from pydantic import BaseModel, ConfigDict, Field, field_validator


MAX_TTS_TEXT_CHARS = 2000


class TTSynthesizeRequest(BaseModel):
    """Text generated by ASTA that the user explicitly asks to hear."""

    model_config = ConfigDict(extra="forbid")

    text: str = Field(..., min_length=1, max_length=MAX_TTS_TEXT_CHARS)

    @field_validator("text")
    @classmethod
    def validate_text(cls, value: str) -> str:
        cleaned = value.strip()
        if not cleaned:
            raise ValueError("must not be blank")
        return cleaned


class TTSStatusResponse(BaseModel):
    """Non-sensitive public status of the local TTS service."""

    enabled: bool
    available: bool
    voice: str
    max_text_chars: int
    max_audio_bytes: int
